-- Neon „KC Core Mirror“: Zieltabellen für DP2-Tage und Club-App-Wunscheingang (29.09.2026, nur CREATE)
create table if not exists public.kc_dp_days_published (org_id text, project_id text, event_id text, work_date date, day_type text, day_start numeric(4,2), day_end numeric(4,2), core_start numeric(4,2), core_end numeric(4,2), pre_open_minutes integer, demand jsonb, program jsonb, label text, status text, source text, source_version text, payload jsonb, checksum text, published_at timestamp with time zone, updated_at timestamp with time zone, primary key (org_id, event_id, work_date));
create table if not exists public.kc_dp_wish_inbox (id uuid, org_id text, project_id text, event_id text, person_id text, source text, contract text, revision integer, status text, entries jsonb, standby jsonb, comment text, share_with_colleagues boolean, submitted_at timestamp with time zone, taken_at timestamp with time zone, taken_by uuid, taken_revision integer, result jsonb, updated_at timestamp with time zone, primary key (id));
